"""Finite SHA-bound reviews for the final source-readable Addition residual queue."""
from experiments.ontology_addition_b03_references import GAUGE, result as preserving_result
from experiments.ontology_addition_b03c1_references import result as changing_result


def preserve(note, code, updates):
    reviewed = preserving_result(note, code)
    reviewed['reviewer'] = 'addition-source-pair-adjudication-v15'
    reviewed['evidence'][0]['kind'] = 'directly source-adjudicated V15 coordinate-gauge transition'
    reviewed['fingerprint'].update(updates)
    return reviewed


def change(changed, note, code, updates):
    reviewed = changing_result(GAUGE, changed, note, code, updates)
    reviewed['reviewer'] = 'addition-source-pair-adjudication-v15'
    reviewed['evidence'][0]['kind'] = 'directly source-adjudicated V15 mechanism transition'
    return reviewed


